package com.campuseventhub;
import java.io.IOException;import java.sql.*;import javax.servlet.ServletException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;
@WebServlet("/markAttendance") public class MarkAttendanceServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{HttpSession s=r.getSession(false);if(s==null||s.getAttribute("admin_id")==null){p.sendRedirect("admin-login.jsp");return;}try(Connection c=DBConnection.getConnection()){PreparedStatement x=c.prepareStatement("UPDATE event_registrations SET attended=NOT attended WHERE registration_id=? AND status='Approved'");x.setInt(1,Integer.parseInt(r.getParameter("registration_id")));x.executeUpdate();p.sendRedirect("viewRegistrations");}catch(Exception e){p.setContentType("text/html;charset=UTF-8");p.getWriter().println("<h2>Error: "+e.getMessage()+"</h2>");}}}
